def format_bytes(n):
    """Return a human-readable size string, e.g. '1.5 KB' for 1536 bytes."""
    unit = "B"
    value = float(n)
    for unit in ("B", "KB", "MB", "GB", "TB", "PB"):
        if value < 1024 or unit == "PB":
            if unit == "B":
                return f"{int(value)} {unit}"
            return f"{value:.1f} {unit}"
        value /= 1024
    return f"{value:.1f} PB"
